"""Module 04 — Amplifier stage coupling and positive/negative feedback (Floyd §6–6, §7–2, §12–3; EASA M04 SM01 pp.49–53)."""
import math
from hx import *
def module(lang):
    f = lambda x, d=2: f'{x:,.{d}f}'
    K = [tr(f'Phần {i} · ' + a, f'Part {i} · ' + b) for i, a, b in ((1, 'Nền tảng', 'Foundations'), (2, 'Phương pháp', 'Methods'), (3, 'Ví dụ từ sách', 'Book examples'), (4, 'Sai lầm và mở rộng', 'Pitfalls and extensions'), (5, 'Ứng dụng và tổng kết', 'Applications and summary'))]
    P = []
    s1 = sl(ul([tr('Một tầng dùng một transistor cho độ lợi điện áp chỉ khoảng 10–100 (EASA)', 'One single-transistor stage gives a voltage gain of only about 10–100 (EASA)'), tr('Ghép tầng (cascade) để có độ lợi lớn: độ lợi tổng là TÍCH các độ lợi', 'Cascading gives large gain: the total gain is the PRODUCT of the stage gains')]) + formula(tr('Độ lợi tổng', 'Overall gain'), 'Av(tổng) = Av1 · Av2 · … · Avn   ;   dB(tổng) = dB1 + dB2 + … + dBn'.replace('tổng', tr('tổng', 'total'))),
            K[0], tr('Khuếch đại ghép tầng', 'Cascade amplifiers'), tr('Tính theo dB thì phép nhân trở thành phép cộng — cách tính nhẩm tiện hơn.', 'In decibels multiplication becomes addition — handier for mental arithmetic.'))
