    P.append(dict(title=tr('Ví dụ và thiết kế', 'Examples and design'), bullets=[tr('Độ lợi nhiều tầng', 'Multistage gain'), tr('Đẩy kéo, lớp C', 'Push-pull, class C'), tr('Thiết kế', 'Design')], slides=[s9, s10, s11]))
